<?php
namespace EventFlow\Tests\Unit\Presentation\Api;
use DateTimeImmutable;use EventFlow\Application\Authorization\PrincipalContext;use EventFlow\Application\Error\RequestIdFactory;use EventFlow\Application\Idempotency\{IdempotencyOutcome,IdempotencyResultReference};use EventFlow\Application\Import\{ImportAdministration,ImportApplyRequest,ImportJobPage,ImportJobRecord,ImportResult,ImportRowPage,ImportRowRecord,ImportRowStatus,ImportStaging,ImportStatus,ImportUploadGuard,UploadedFile};use EventFlow\Application\Persistence\EventScope;use EventFlow\Application\Security\SecureRandom;use EventFlow\Presentation\Api\{AuthenticatedPrincipalResolver,AuthenticatedRequestContextFactory,ImportAdministrationController,ImportAdministrationPresenter,ImportAdministrationRequestMapper,ImportAdministrationRouteRegistrar,ImportUploadController,RestRequest,RestRouteRegistry};use PHPUnit\Framework\TestCase;
final class ImportAdministrationControllerTest extends TestCase
{public function testRoutesCoverUploadQueriesReviewAndCommands():void{[$admin,$upload]=$this->controllers(new ImportAdminPort());$routes=new ImportAdminRoutes();(new ImportAdministrationRouteRegistrar($admin,$upload))->register($routes);self::assertSame(['GET eventflow/v1/events/(?P<event_id>\d+)/imports','POST eventflow/v1/events/(?P<event_id>\d+)/imports','GET eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)','POST eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/parse','POST eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/dry-run','POST eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/apply','POST eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/cancel','GET eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/rows','GET eventflow/v1/events/(?P<event_id>\d+)/imports/(?P<import_job_id>\d+)/result'],$routes->registered);}public function testQueriesRowsResultApplyAndCancelMapStrictly():void{$port=new ImportAdminPort();[$admin]=$this->controllers($port);$page=$admin->list(new RestRequest(routeParameters:['event_id'=>'9'],queryParameters:['limit'=>'25','after'=>'70','status'=>'validated']));self::assertSame([25,70,ImportStatus::VALIDATED],$port->page);self::assertSame(72,$page->body()['meta']['next_after']);$rows=$admin->rows(new RestRequest(routeParameters:['event_id'=>'9','import_job_id'=>'71'],queryParameters:['status'=>'ready']));self::assertSame('Guest',$rows->body()['data'][0]['normalized_data']['primary_name']);$result=$admin->result(new RestRequest(routeParameters:['event_id'=>'9','import_job_id'=>'71']));self::assertSame(17,$result->body()['data']['ready_rows']);$apply=$admin->apply(new RestRequest(['If-Match'=>'3','Idempotency-Key'=>'import-apply-001'],[],['event_id'=>'9','import_job_id'=>'71']));self::assertSame([71,3,'import-apply-001'],$port->applyInput);self::assertSame(91,$apply->body()['data']['worker_job_id']);self::assertSame('"4"',$apply->headers()['ETag']);$cancel=$admin->cancel(new RestRequest(['If-Match'=>'4','Idempotency-Key'=>'import-cancel-001'],[],['event_id'=>'9','import_job_id'=>'71']));self::assertSame('cancelled',$cancel->body()['data']['status']);}public function testUploadUsesTypedFileGuardAndNeverJsonPath():void{$port=new ImportAdminPort();[, $upload]=$this->controllers($port);$response=$upload->create(new RestRequest(['Idempotency-Key'=>'import-upload-001'],[],['event_id'=>'9'],files:['source'=>new UploadedFile('guests.csv','untrusted.tmp',120,0)]));self::assertSame(['trusted.csv','guests.csv','import-upload-001'],$port->staged);self::assertSame(201,$response->status());self::assertSame('"1"',$response->headers()['ETag']);}private function controllers(ImportAdminPort$port):array{$contexts=new AuthenticatedRequestContextFactory(new ImportAdminPrincipal(),new RequestIdFactory(new ImportAdminRandom()));$requests=new ImportAdministrationRequestMapper();$presenter=new ImportAdministrationPresenter();return[new ImportAdministrationController($port,$contexts,$requests,$presenter),new ImportUploadController($port,new ImportAdminGuard(),$contexts,$requests,$presenter)];}}
final class ImportAdminRoutes implements RestRouteRegistry{public array$registered=[];public function registerPublicGet(string$n,string$r,callable$h):void{}public function registerPublicPost(string$n,string$r,callable$h):void{}public function registerPublicPut(string$n,string$r,callable$h):void{}public function registerAuthenticatedGet(string$n,string$r,callable$h):void{$this->registered[]='GET '.$n.$r;}public function registerAuthenticatedPost(string$n,string$r,callable$h):void{$this->registered[]='POST '.$n.$r;}public function registerAuthenticatedPatch(string$n,string$r,callable$h):void{}}
final readonly class ImportAdminPrincipal implements AuthenticatedPrincipalResolver{public function resolve(RestRequest$r):PrincipalContext{return PrincipalContext::wordpressUser(7);}}final readonly class ImportAdminRandom implements SecureRandom{public function hex(int$b):string{return str_repeat('6',$b*2);}}final readonly class ImportAdminGuard implements ImportUploadGuard{public function withTrustedUpload(UploadedFile$f,callable$o):mixed{return$o('trusted.csv','guests.csv');}}
final class ImportAdminPort implements ImportAdministration,ImportStaging
{public array$page=[];public array$applyInput=[];public array$staged=[];public function list(PrincipalContext$p,EventScope$s,int$l=50,?int$a=null,?ImportStatus$status=null):ImportJobPage{$this->page=[$l,$a,$status];return new ImportJobPage([$this->job()],72);}public function read(PrincipalContext$p,EventScope$s,int$id):ImportJobRecord{return$this->job();}public function rows(PrincipalContext$p,EventScope$s,int$id,int$l=100,?int$a=null,?ImportRowStatus$status=null):ImportRowPage{return new ImportRowPage([new ImportRowRecord(81,71,1,ImportRowStatus::READY,['Name'=>'Guest'],['primary_name'=>'Guest'])],null);}public function result(PrincipalContext$p,EventScope$s,int$id):ImportResult{return new ImportResult(71,ImportStatus::VALIDATED,20,17,1,2,0,0,0);}public function requestApply(PrincipalContext$p,EventScope$s,int$id,int$r,string$key):IdempotencyOutcome{$this->applyInput=[$id,$r,$key];return new IdempotencyOutcome(false,new IdempotencyResultReference('import_job',$id,202),new ImportApplyRequest($this->job(ImportStatus::APPLYING,4),91));}public function cancel(PrincipalContext$p,EventScope$s,int$id,int$r,string$key):IdempotencyOutcome{return new IdempotencyOutcome(false,new IdempotencyResultReference('import_job',$id,200),$this->job(ImportStatus::CANCELLED,5));}public function stage(PrincipalContext$p,EventScope$s,string$path,string$key,?string$name=null):IdempotencyOutcome{$this->staged=[$path,$name,$key];return new IdempotencyOutcome(false,new IdempotencyResultReference('import_job',71,201),$this->job(ImportStatus::STAGED,1));}private function job(ImportStatus$status=ImportStatus::VALIDATED,int$revision=3):ImportJobRecord{return new ImportJobRecord(71,new EventScope(9),$status,'guests.csv',hash('sha256','file'),20,17,2,0,0,revision:$revision,warningRows:1,uploadedAt:new DateTimeImmutable('2026-08-19T18:00:00Z'));}}
